-- Name: tool; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tool (
    id integer NOT NULL,
    name character varying(100) NOT NULL,
    category character varying(1024),
    visible boolean NOT NULL,
    operational boolean NOT NULL,
    location character varying(100),
    phone_number character varying(100),
    notification_email_address character varying(254),
    reservation_horizon integer,
    minimum_usage_block_time integer,
    maximum_usage_block_time integer,
    maximum_reservations_per_day integer,
    minimum_time_between_reservations integer,
    maximum_future_reservation_time integer,
    missed_reservation_threshold integer,
    interlock_id integer,
    primary_owner_id integer,
    requires_area_access_id integer,
    grant_badge_reader_access_upon_qualification character varying(100),
    policy_off_end_time time without time zone,
    policy_off_start_time time without time zone,
    policy_off_between_times boolean NOT NULL,
    policy_off_weekend boolean NOT NULL,
    grant_physical_access_level_upon_qualification_id integer,
    parent_tool_id integer,
    description text,
    serial character varying(100),
    image character varying(100) NOT NULL,
    tool_calendar_color character varying(9) NOT NULL,
    qualifications_never_expire boolean NOT NULL,
    ask_to_leave_area_when_done_using boolean NOT NULL,
    _operation_mode integer NOT NULL,
    max_delayed_logoff integer,
    maximum_future_reservations integer,
    properties jsonb,
    abuse_weight integer NOT NULL,
    problem_shutdown_enabled boolean NOT NULL,
    requires_area_occupancy_minimum integer,
    CONSTRAINT "NEMO_tool_max_delayed_logoff_check" CHECK ((max_delayed_logoff >= 0)),
    CONSTRAINT "NEMO_tool_maximum_future_reservation_time_e8336012_check" CHECK ((maximum_future_reservation_time >= 0)),
    CONSTRAINT "NEMO_tool_maximum_future_reservations_check" CHECK ((maximum_future_reservations >= 0)),
    CONSTRAINT "NEMO_tool_maximum_reservations_per_day_277896cf_check" CHECK ((maximum_reservations_per_day >= 0)),
    CONSTRAINT "NEMO_tool_maximum_usage_block_time_6bafe2ff_check" CHECK ((maximum_usage_block_time >= 0)),
    CONSTRAINT "NEMO_tool_minimum_time_between_reservations_5fe070ac_check" CHECK ((minimum_time_between_reservations >= 0)),
    CONSTRAINT "NEMO_tool_minimum_usage_block_time_b27f5482_check" CHECK ((minimum_usage_block_time >= 0)),
    CONSTRAINT "NEMO_tool_missed_reservation_threshold_b7d49cb4_check" CHECK ((missed_reservation_threshold >= 0)),
    CONSTRAINT "NEMO_tool_requires_area_occupancy_minimum_check" CHECK ((requires_area_occupancy_minimum >= 0)),
    CONSTRAINT "NEMO_tool_reservation_horizon_d147eadb_check" CHECK ((reservation_horizon >= 0))
);



